 add(20,r'S=2\pi r^2+2\pi rh','Закрытая цилиндрическая банка: при заданной полной поверхности максимизируй объём. В ответе отношение диаметра к высоте.',[field('ratio','Диаметр / высота','1')],r'h=S/(2\pi r)-r,\quad V=Sr/2-\pi r^3',r'V^\prime=S/2-3\pi r^2=0',r'S=6\pi r^2\Rightarrow h=2r;\quad V^{\prime\prime}<0',r'2r/h=1')
